use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let rows = input.as_array().unwrap();
    let mut result = Vec::new();
    for row in rows {
        let key = row.as_array().unwrap()[0].as_i64().unwrap();
        let value = row.as_array().unwrap()[1].as_i64().unwrap();
        result.push(Value::from(vec![Value::from(key), Value::from(value)]));
    }
    result.sort_by_key(|r| r[0]);
    Value::from(result)
}
